#!/usr/bin/env bash
# =========================================== # Secure RAG - Backup Script # =========================================== set -euo pipefail  BACKUP_DIR="./backups/$(date +%Y%m%d_%H%M%S)" mkdir -p "$BACKUP_DIR"  echo "Starting backup at $(date)"  # PostgreSQL backup echo "Backing up PostgreSQL..." docker compose exec -T postgres pg_dump \   -U "${POSTGRES_USER:-secure_rag_user}" \   -d "${POSTGRES_DB:-secure_rag_db}" \   --format=custom \   --compress=9 \   > "$BACKUP_DIR/postgres.dump"  echo "PostgreSQL backup complete: $BACKUP_DIR/postgres.dump"  # Redis backup echo "Backing up Redis..." docker compose exec -T redis redis-cli BGSAVE sleep 2 docker compose cp redis:/data/dump.rdb "$BACKUP_DIR/redis_dump.rdb" 2>/dev/null || echo "Redis dump not found (may be empty)" echo "Redis backup complete"  # ChromaDB backup echo "Backing up ChromaDB..." docker compose cp chromadb:/chroma/chroma "$BACKUP_DIR/chroma_data" 2>/dev/null || echo "ChromaDB data copy failed" echo "ChromaDB backup complete"  # Create backup manifest cat > "$BACKUP_DIR/manifest.json" << EOF {   "timestamp": "$(date -u +%Y-%m-%dT%H:%M:%SZ)",   "services": ["postgres", "redis", "chromadb"],   "files": {     "postgres": "postgres.dump",     "redis": "redis_dump.rdb",     "chroma": "chroma_data"   } } EOF  echo "Backup complete: $BACKUP_DIR" echo "Size: $(du -sh "$BACKUP_DIR" | cut -f1)"  # Cleanup old backups (keep last 7) echo "Cleaning old backups..." ls -dt ./backups/*/ 2>/dev/null | tail -n +8 | xargs rm -rf 2>/dev/null || true echo "Backup maintenance complete"
